from pathlib import Path
names=['Sapphire Cinema','Sapphire Editorial','Sapphire Panorama','Sapphire Channel','Sapphire Collection']
descriptions=['Große Kinobühne mit Text im Bild. Die engste Weiterentwicklung von Studio Sapphire.','Ruhige geteilte Startseite, klare Typografie und stärkerer Fokus auf digitale Publikationen.','Zentrierte Botschaft über einer breiten Bildbühne. Großzügig und etwas offener innerhalb der dunklen Palette.','Ein Lernkanal mit seitlicher Navigation, Hauptformat und sichtbarer Themenliste.','Eine asymmetrische Kollektion mit breitem Filmrahmen und überlagerter vertikaler Medienkarte.']
css='''*{box-sizing:border-box}body{margin:0;background:#0d182b;color:#edf3ff;font:16px/1.6 "Segoe UI",Arial,sans-serif}main{max-width:1500px;margin:auto;padding:50px 40px}h1{font-size:56px;line-height:1.06;letter-spacing:-.045em;margin:14px 0 25px;max-width:1000px}h2{font-size:29px;line-height:1.15;margin:14px 0}p{color:#afc2dd;max-width:900px}a{color:inherit}nav{display:flex;gap:12px;flex-wrap:wrap;margin:27px 0 35px}nav a,.btn{display:inline-block;padding:10px 16px;border:1px solid #415d88;background:#172d4b;text-decoration:none;border-radius:5px;font-size:13px}.kicker{font:11px Consolas,monospace;letter-spacing:.13em;color:#9fc3fa}.grid{display:grid;grid-template-columns:1fr 1fr;gap:28px}.card{border:1px solid #2e496e;border-radius:8px;overflow:hidden;background:#13253e;min-width:0}.card img{width:100%;display:block}.copy{padding:25px}.copy p{font-size:14px}.links{display:flex;flex-wrap:wrap;gap:13px;font-size:12px;margin-top:20px}.board{width:1700px;padding:35px}.board h1{font-size:48px}.board .topview{display:grid;grid-template-columns:1280px 300px;gap:28px}.board figure{margin:0;background:#13253e;border:1px solid #345178}.board figure img{display:block;width:100%}.board figcaption{padding:10px 17px;font-size:16px}.board .subgrid{display:grid;grid-template-columns:1fr 1fr;gap:25px;margin-top:28px}.overview{width:1800px;padding:40px}.overview .grid{grid-template-columns:repeat(3,1fr);gap:22px}.overview h1{font-size:48px}.overview .copy{padding:20px}.overview h2{font-size:27px}.overview p{font-size:15px}@media(max-width:760px){main{padding:30px 19px}h1{font-size:40px}.grid{grid-template-columns:1fr}}'''
Path('gallery.css').write_text(css,encoding='utf-8')
def shell(title,body,cl=''):return f'<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="stylesheet" href="gallery.css"><body class="{cl}">{body}</body></html>'
cards=[]
for n,name in enumerate(names,1):
 links=''.join(f'<a href="variante-{n}.html?page={p}&lang=de">{label}</a>' for p,label in [('home','Startseite'),('library','Bibliothek'),('product','Produkt'),('tools','Tools'),('media','Studio')])
 cards.append(f'<article class="card"><a href="variante-{n}.html?lang=de"><img src="screenshots/0{n}-home.jpg" alt="Website {name}"></a><div class="copy"><div class="kicker">VARIANTE 0{n}</div><h2>{name}</h2><p>{descriptions[n-1]}</p><a class="btn" href="variante-{n}.html?lang=de">Website ausprobieren ↗</a><div class="links">{links}<a href="vorlage-0{n}.jpg">Bildvorlage</a><a href="screenshots/0{n}-home-full.jpg">Ganze Startseite</a></div></div></article>')
 title=f'<div class="kicker">SCUTORIA / STUDIO SAPPHIRE / VARIANTE 0{n}</div><h1>{name}</h1><p>{descriptions[n-1]}</p>'
 top=f'<div class="topview"><figure><img src="screenshots/0{n}-home.jpg"><figcaption>Startseite / Desktop</figcaption></figure><figure><img src="screenshots/0{n}-mobile.jpg"><figcaption>Startseite / Mobil</figcaption></figure></div>'
 subs=''.join(f'<figure><img src="screenshots/0{n}-{p}.jpg"><figcaption>{label}</figcaption></figure>' for p,label in [('library','Bibliothek'),('product','Produktdetail'),('tools','Tools'),('media','Studio')])
 Path(f'board-{n}.html').write_text(shell(name,title+top+'<div class="subgrid">'+subs+'</div><p>Lokaler Designprototyp · zusätzliche Katalogtitel und Medienformate sind Konzepte · Animationen in den HTML-Varianten.</p>','board'),encoding='utf-8')
Path('index.html').write_text(shell('Scutoria · Fünf Studio-Sapphire-Varianten','<main><div class="kicker">SCUTORIA / FÜNF DUNKLE STUDIO-VARIANTEN</div><h1>Eine Bildwelt.<br>Fünf eigenständige Auftritte.</h1><p>Aus Studio Sapphire entwickelt: fünf unterschiedliche Seitenaufbauten innerhalb der Navy-Saphir-Farbwelt. Jede Variante enthält Startseite, Bibliothek, Produktdetail, Tools und Studio. Desktop und Mobil, Deutsch und Englisch.</p><nav><a href="CLAUDE-FUENF-SAPPHIRE.md">Präziser Claude-Brief</a><a href="SCUTORIA-5-SAPPHIRE.zip">Komplettpaket</a><a href="vergleich.jpg">Bildvergleich</a></nav><div class="grid">'+''.join(cards)+'</div><p>Die gemeinsame Studio-Illustration wird bewusst wiederverwendet, damit Layout und Informationshierarchie direkt vergleichbar bleiben. Die Livewebsite wurde nicht verändert.</p></main>'),encoding='utf-8')
mini=''.join(f'<article class="card"><img src="screenshots/0{n}-home.jpg"><div class="copy"><div class="kicker">VARIANTE 0{n}</div><h2>{names[n-1]}</h2><p>{descriptions[n-1]}</p></div></article>' for n in range(1,6))
Path('overview.html').write_text(shell('Fünf dunkle Studio-Sapphire-Varianten','<div class="kicker">SCUTORIA / STUDIO SAPPHIRE</div><h1>Fünf dunkle Websitevarianten.</h1><p>Gleiche filmische Bildwelt, unterschiedliche Kompositionen. Jeweils mit Bibliothek, Produktdetail, Tools und Studio.</p><div class="grid">'+mini+'</div>','overview'),encoding='utf-8')
